#include <iostream>
#include <array>
#include <string_view>

int main() {
    // Legacy C-style array of pointers to const char
    const char *suitC[4] = {"Hearts", "Diamonds", "Clubs", "Spades"};

    // Modern C++17 array of string_view (constexpr, zero runtime overhead)
    constexpr std::array<std::string_view, 4> suitModern = {
        "Hearts", "Diamonds", "Clubs", "Spades"
    };

    std::cout << "C-style pointer array:\n";
    for (size_t i = 0; i < 4; ++i) {
        std::cout << "suitC[" << i << "] = " << suitC[i] << '\n';
    }

    std::cout << "\nModern C++17 string_view array:\n";
    for (size_t i = 0; i < suitModern.size(); ++i) {
        std::cout << "suitModern[" << i << "] = " << suitModern[i]
                  << " (length: " << suitModern[i].size() << ")\n";
    }

    return 0;
}

#include <iostream>
#include <array>
#include <string_view>

constexpr size_t SUITS = 4;
constexpr size_t FACES = 13;

int main() {
    // Top-down stepwise refinement: mapping card coordinates to text
    constexpr std::array<std::string_view, SUITS> suits = {
        "Hearts", "Diamonds", "Clubs", "Spades"
    };

    constexpr std::array<std::string_view, FACES> faces = {
        "Ace", "Deuce", "Three", "Four", "Five", "Six",
        "Seven", "Eight", "Nine", "Ten", "Jack", "Queen", "King"
    };

    // Pre-populated sample deck demonstrating deterministic card deal
    // Fig. 7.23 example: deck[2][12] represents King of Clubs
    std::array<std::array<unsigned int, FACES>, SUITS> deck{};
    deck[0][8] = 1;  // Card 1: Nine of Hearts
    deck[2][4] = 2;  // Card 2: Five of Clubs
    deck[3][11] = 3; // Card 3: Queen of Spades
    deck[2][12] = 4; // Card 4: King of Clubs

    // Deal cards 1 to 4 using the nested loop search from Refinement 3
    for (unsigned int card = 1; card <= 4; ++card) {
        for (size_t row = 0; row < SUITS; ++row) {
            for (size_t col = 0; col < FACES; ++col) {
                if (deck[row][col] == card) {
                    std::cout << "Card " << card << ": "
                              << faces[col] << " of " << suits[row] << '\n';
                }
            }
        }
    }

    return 0;
}
